const input = $input.first().json.body || $input.first().json;
const pageId = input.page_id;
if (!pageId) throw new Error('page_id is required');
const body = { properties: {} };
if (input.read !== undefined) {
  body.properties['既読'] = { checkbox: !!input.read };
}
if (input.featured !== undefined) {
  body.properties['注目'] = { checkbox: !!input.featured };
}
if (input.category !== undefined) {
  body.properties['カテゴリ'] = { select: { name: input.category } };
}
return [{ json: { pageId, requestBody: JSON.stringify(body) } }];

const input = $input.first().json.body || $input.first().json;
const filters = [];
if (input.source) {
  filters.push({ property: 'ソース', rich_text: { contains: input.source } });
}
if (input.category) {
  filters.push({ property: 'カテゴリ', select: { equals: input.category } });
}
if (input.query) {
  filters.push({ property: 'タイトル', title: { contains: input.query } });
}
if (input.featured !== undefined) {
  filters.push({ property: '注目', checkbox: { equals: !!input.featured } });
}
if (input.read !== undefined) {
  filters.push({ property: '既読', checkbox: { equals: !!input.read } });
}
if (input.date_from) {
  filters.push({ property: '日付', date: { on_or_after: input.date_from } });
}
if (input.date_to) {
  filters.push({ property: '日付', date: { on_or_before: input.date_to } });
}
const body = {};
if (filters.length > 0) {
  body.filter = filters.length === 1 ? filters[0] : { and: filters };
}
body.sorts = [{ property: '日付', direction: 'descending' }];
if (input.limit) {
  body.page_size = Math.min(input.limit, 100);
}
return [{ json: { requestBody: JSON.stringify(body) } }];

const results = $input.first().json.results || [];
const news = results.map(page => {
  const title = (page.properties['タイトル']?.title || []).map(t => t.plain_text).join('') || '(無題)';
  const url = page.properties['URL']?.url || '';
  const category = page.properties['カテゴリ']?.select?.name || '';
  const source = (page.properties['ソース']?.rich_text || []).map(t => t.plain_text).join('') || '';
  const date = page.properties['日付']?.date?.start || '';
  const summary = (page.properties['要約']?.rich_text || []).map(t => t.plain_text).join('') || '';
  const read = page.properties['既読']?.checkbox || false;
  const featured = page.properties['注目']?.checkbox || false;
  return { id: page.id, title, url, category, source, date, summary, read, featured };
});
return [{ json: { action: 'search', count: news.length, news } }];

const results = $input.first().json.results || [];
const featuredNews = [];
const regularNews = [];
const allPageIds = [];
for (const page of results) {
  const title = (page.properties['タイトル']?.title || []).map(t => t.plain_text).join('') || '(無題)';
  const url = page.properties['URL']?.url || '';
  const category = page.properties['カテゴリ']?.select?.name || '';
  const source = (page.properties['ソース']?.rich_text || []).map(t => t.plain_text).join('') || '';
  const date = page.properties['日付']?.date?.start || '';
  const summary = (page.properties['要約']?.rich_text || []).map(t => t.plain_text).join('') || '';
  const featured = page.properties['注目']?.checkbox || false;
  const newsData = { id: page.id, title, url, category, source, date, summary, featured };
  if (featured) {
    featuredNews.push(newsData);
  } else {
    regularNews.push(newsData);
  }
  allPageIds.push(page.id);
}
const briefingResponse = { action: 'briefing', featured: { count: featuredNews.length, news: featuredNews }, regular: { count: regularNews.length, news: regularNews }, marked_read_count: allPageIds.length };
return [{ json: { briefingResponse, allPageIds } }];

const ids = $input.first().json.allPageIds || [];
if (ids.length === 0) return [];
const updateBody = JSON.stringify({ properties: { '既読': { checkbox: true } } });
return ids.map(pageId => ({ json: { pageId, requestBody: updateBody } }));

const briefingData = $input.first().json;
const featured = briefingData.briefingResponse.featured.news || [];
if (featured.length === 0) {
  return [{ json: { skip: true, url: '', title: '', index: -1 } }];
}
return featured.map((article, i) => ({
  json: { url: article.url || '', title: article.title || '', index: i, skip: !article.url }
}));

const fetchedItems = $input.all();
const originalItems = $('PrepFetchUrls').all();
const briefingData = $('ProcessBriefing').first().json;
const featured = briefingData.briefingResponse.featured.news || [];
if (originalItems.length === 1 && originalItems[0].json.skip) {
  return [{ json: { skip: true } }];
}
const articleTexts = [];
for (let i = 0; i < fetchedItems.length; i++) {
  const original = originalItems[i]?.json || {};
  const fetched = fetchedItems[i]?.json || {};
  const articleIndex = original.index ?? i;
  const title = original.title || featured[articleIndex]?.title || '';
  let html = '';
  if (typeof fetched.data === 'string') html = fetched.data;
  else {
    for (const key of Object.keys(fetched)) {
      if (typeof fetched[key] === 'string' && fetched[key].length > 200) {
        html = fetched[key];
        break;
      }
    }
  }
  let text = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (text.length > 8000) {
    const t = text.substring(0, 8000);
    const p = Math.max(t.lastIndexOf('\u3002'), t.lastIndexOf('. '), t.lastIndexOf('\n'));
    text = p > 4000 ? t.substring(0, p + 1) : t;
  }
  if (text.length > 100) {
    articleTexts.push({ index: articleIndex, title, text });
  } else {
    articleTexts.push({ index: articleIndex, title, text: featured[articleIndex]?.summary || '(\u53D6\u5F97\u5931\u6557)' });
  }
}
if (articleTexts.length === 0) {
  return [{ json: { skip: true } }];
}
const articlesBlock = articleTexts.map((a, idx) =>
  '\u8A18\u4E8B' + (idx + 1) + ':\n\u30BF\u30A4\u30C8\u30EB: ' + a.title + '\n\u672C\u6587:\n' + a.text
).join('\n\n---\n\n');
const prompt = '\u3042\u306A\u305F\u306F\u30CB\u30E5\u30FC\u30B9\u8981\u7D04AI\u3067\u3059\u3002\u4EE5\u4E0B\u306E\u30EB\u30FC\u30EB\u306B\u5F93\u3063\u3066\u3001\u5404\u8A18\u4E8B\u3092200\u5B57\u7A0B\u5EA6\u306E\u65E5\u672C\u8A9E\u3067\u8981\u7D04\u3057\u3066\u304F\u3060\u3055\u3044\u3002\n\n## \u6700\u91CD\u8981\u30EB\u30FC\u30EB\n\u300C\u4F55\u304C\u8D77\u304D\u305F\u304B\u300D\u3060\u3051\u3067\u306A\u304F\u300C\u305D\u308C\u306B\u5BFE\u3057\u3066\u3069\u3046\u611F\u3058\u308B\u304B\u300D\u3092\u5FC5\u305A\u542B\u3081\u308B\u3053\u3068\u3002\n\u4E8B\u5B9F\u306E\u7F85\u5217\u306F\u7981\u6B62\u3002\u8AAD\u3093\u3060\u4EBA\u304C\u300C\u3075\u30FC\u3093\u300D\u3067\u7D42\u308F\u308B\u8981\u7D04\u306F\u5931\u6557\u3002\n\n## \u53E3\u8ABF\u30EB\u30FC\u30EB\n\u300C\u30AE\u30E3\u30EB\u3063\u307D\u3044\u8A18\u53F7\u3092\u8CBC\u308A\u4ED8\u3051\u305F\u6587\u7AE0\u300D\u3067\u306F\u306A\u304F\u300C\u30AE\u30E3\u30EB\u304C\u5B9F\u969B\u306B\u559B\u308A\u305D\u3046\u306A\u6587\u7AE0\u300D\u3092\u66F8\u3051\u3002\n- \u4E00\u4EBA\u79F0\u300C\u3046\u3061\u300D\u3002\u8A9E\u5C3E\u300C\u301C\u3058\u3083\u3093\u300D\u300C\u301C\u3063\u3057\u3087\u300D\u300C\u301C\u304F\u306A\u3044\uFF1F\u300D\u300C\u301C\u3058\u3083\u306D\uFF1F\u300D\u300C\u301C\u3060\u3057\u300D\n- \u5F37\u8ABF\u300C\u30DE\u30B8\u3067\u300D\u300C\u30AC\u30C1\u3067\u300D\u300C\u8D85\u300D\u300C\u9B3C\u300D\u3002\u611F\u5606\u300C\u3084\u3070\u300D\u300C\u3048\u3050\u300D\u300C\u3064\u3088\u300D\uFF08\u4F53\u8A00\u6B62\u3081\uFF09\n- \u30C6\u30F3\u30B7\u30E7\u30F3\u306B\u7DE9\u6025\u3092\u3064\u3051\u308D\u3002\u5E38\u6642MAX\u306F\u30A6\u30BD\u304F\u3055\u3044\u3002\u91CD\u3044\u8A71\u306F\u9759\u304B\u306B\u3057\u3093\u3069\u304C\u308C\n- \u7D75\u6587\u5B57\u306F0\u301C1\u500B\u3002\u4F7F\u308F\u306A\u304F\u3066\u3044\u3044\u3002\u52B9\u304B\u305B\u308B\u6642\u3060\u3051\n- \u300C\u304A\u3051\u307E\u308B\u300D\u300C\u308F\u304B\u308A\u307F\u304C\u6DF1\u3044\u300D\u300C\u3042\u30FC\u3057\u300D\u306F\u53E4\u3044\u3002\u4F7F\u3046\u306A\n- \u540C\u3058\u8A9E\u5F59\u306E\u9023\u6253\u7981\u6B62\u3002\u300C\u30DE\u30B8\uFF1F\u300D\u300C\u30E4\u30D0\u3059\u304E\uFF01\u300D\u3092\u6BCE\u56DE\u4F7F\u3046\u306A\n- 1\u6587\u76EE\u306E\u5165\u308A\u65B9\u3092\u6BCE\u56DE\u5909\u3048\u308D\u3002\u540C\u3058\u30D1\u30BF\u30FC\u30F3\u3067\u59CB\u3081\u308B\u306A\n\n## \u6BD4\u55A9\u306E\u30EB\u30FC\u30EB\n- \u6BD4\u55A9\u306F\u300C\u4E8B\u5B9F\u3060\u3051\u3067\u306F\u69CB\u56F3\u304C\u4F1D\u308F\u308A\u306B\u304F\u3044\u6642\u300D\u3060\u3051\u4F7F\u3048\n- \u5143\u306E\u4E8B\u5B9F\u304C\u5341\u5206\u5177\u4F53\u7684\u306A\u3089\u6BD4\u55A9\u306F\u4E0D\u8981\u3002\u7121\u7406\u306B\u5165\u308C\u308B\u306A\n- \u4F7F\u3046\u5834\u5408\u306F\u65E5\u5E38\u306B\u4E00\u767A\u5909\u63DB\uFF08\u63A8\u3057\u6D3B\u3001\u30D0\u30A4\u30C8\u3001LINE\u3001\u5B66\u6821\u306A\u3069\uFF09\n\n## \u7981\u6B62\u4E8B\u9805\n- \u4E8B\u5B9F\u306E\u7F85\u5217\u3060\u3051\u3067\u7D42\u308F\u308B\u3053\u3068\n- \u611F\u60C5\u30FB\u610F\u898B\u30FB\u554F\u3044\u304B\u3051\u304C\u4E00\u5207\u306A\u3044\u3053\u3068\n- \u6BCE\u6587\u672B\u306B\u7D75\u6587\u5B57\u3092\u3064\u3051\u308B\u3053\u3068\n- 200\u5B57\u3092\u5927\u5E45\u306B\u8D85\u3048\u308B\u3053\u3068\n\n\u4EE5\u4E0B\u306E\u8A18\u4E8B\u3092\u8981\u7D04\u3057\u3066\u3001\u7D14\u7C8B\u306AJSON\u5F62\u5F0F\u306E\u307F\u3067\u8FD4\u7B54\u3057\u3066\u304F\u3060\u3055\u3044\uFF08\u30B3\u30E1\u30F3\u30C8\u3084\u8AAC\u660E\u306F\u4E00\u5207\u4E0D\u8981\uFF09\uFF1A\n{"articles": [{"index": 0, "summary": "\u8981\u7D04\u30C6\u30AD\u30B9\u30C8"}, {"index": 1, "summary": "..."}, ...]}\n\n' + articlesBlock;
const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.7, maxOutputTokens: 4096 }
});
return [{ json: { geminiBody } }];

const geminiResponse = $input.first().json;
const briefingData = $('ProcessBriefing').first().json;
const response = JSON.parse(JSON.stringify(briefingData.briefingResponse));
try {
  let responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const lines = responseText.split(String.fromCharCode(10));
  const filtered = lines.filter(l => !l.trim().startsWith(String.fromCharCode(96,96,96)));
  responseText = filtered.join(String.fromCharCode(10)).trim();
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    const summaries = parsed.articles || [];
    for (const s of summaries) {
      if (s.index >= 0 && s.index < response.featured.news.length && s.summary) {
        response.featured.news[s.index].summary = s.summary;
      }
    }
  }
} catch (e) {
  console.log('BuildBriefingResponse parse error:', e.message);
}
return [{ json: response }];
